Rules.InvariantScript:
Set(varScanCode, Trim(First(Self.Barcodes).Value));
Set(
    varScanAsset,
    LookUp(
        Equipment_Assets,
        Titel = varScanCode || UANumber = varScanCode || SerialNumber = varScanCode
    )
);
Set(varScanSetup, LookUp(Equipment_Setups, Titel = varScanCode));
Set(
    varScanSetupNew,
    Filter(
        Filter(Equipment_Assets, varScanCode in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
If(
    // 1. An individual asset, already queued
    !IsBlank(varScanAsset.'Id (ID)') && varScanAsset.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify(
        "Asset " & varScanCode & " is already in the move list.",
        NotificationType.Warning
    ),
    !IsBlank(varScanAsset.'Id (ID)'),
    Collect(colMoveBuffer, varScanAsset);
    Notify("Asset " & varScanCode & " added.", NotificationType.Success),
    // 2. No asset, so try a setup: Equipment_Setups.Title is the SetupID
    !IsBlank(varScanSetup.'Id (ID)'),
    Collect(colMoveBuffer, varScanSetupNew);
    Notify(
        "Setup " & varScanCode & " and all linked assets added.",
        NotificationType.Success
    ),
    // 3. Nothing found
    Notify(
        "Code " & varScanCode & " not found in assets or setups.",
        NotificationType.Error
    )
)

With(
    {
        room: drpTargetLocation.Selected.Value,
        campus: lblDerivedCampusValue.Text,
        movingASetup: !IsEmpty(Filter(colMoveBuffer, !IsEmpty(Setups)))
    },
    If(
        IsBlank(room),
            "",
        IsBlank(
            LookUp(
                Choices(Equipment_MovementLog.ToLocation),
                Value = room
            ).Value
        ),
            "the movement log, ToLocation",
        !IsEmpty(
            Filter(
                Distinct(colMoveBuffer, 'CurrentLocation (CurrentLocation0)'.Value) As src,
                IsBlank(
                    LookUp(
                        Choices(Equipment_MovementLog.FromLocation),
                        Value = src.Value
                    ).Value
                )
            )
        ),
            "the movement log, FromLocation - a room one of these assets is in now",
        movingASetup && IsBlank(
            LookUp(
                Choices(Equipment_Setups.CurrentLocation),
                Value = room
            ).Value
        ),
            "the setups list, CurrentLocation",
        movingASetup && !IsBlank(campus) && IsBlank(
            LookUp(
                Choices(Equipment_Setups.CurrentCampus),
                Value = campus
            ).Value
        ),
            "the setups list, CurrentCampus",
        ""
    )
)

Set(varMvBlocked, !IsBlank(lblMoveBlocker.Text));
Set(varMvRoom, drpTargetLocation.Selected.Value);
Set(varMvCampus, lblDerivedCampusValue.Text);
Set(varMvAction, If(CountRows(colMoveBuffer) > 1, "Bulk Move", "Relocation"));
If(
    varMvBlocked,
    Notify(lblMoveBlocker.Text, NotificationType.Warning),

    Notify(
        "Moving " & CountRows(colMoveBuffer) & " item(s) to " & varMvRoom & "...",
        NotificationType.Information
    );

    // 1. Log first: FromLocation has to hold the OLD room.
    ForAll(
        colMoveBuffer As buffered,
        Patch(
            Equipment_MovementLog,
            Defaults(Equipment_MovementLog),
            {
                Title: buffered.Titel,
                FromLocation: { Value: buffered.'CurrentLocation (CurrentLocation0)'.Value },
                ToLocation: { Value: varMvRoom },
                MovedBy: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(User().Email),
                    DisplayName: User().FullName,
                    Email: User().Email,
                    Department: "",
                    JobTitle: "",
                    Picture: ""
                },
                ActionType: { Value: varMvAction },
                TimeStamp: Now()
            }
        )
    );

    // 2. Then the assets. LookUp by ID hands Patch a real Equipment_Assets
    //    record; the buffered row comes from a collection whose schema is
    //    merged from several Collect() calls.
    ForAll(
        colMoveBuffer As buffered,
        Patch(
            Equipment_Assets,
            LookUp(Equipment_Assets, 'Id (ID)' = buffered.'Id (ID)'),
            {
                'CurrentLocation (CurrentLocation0)': { Value: varMvRoom },
                CurrentCampus: {
                    Value: Coalesce(varMvCampus, buffered.CurrentCampus.Value)
                },
                LastRelocatedBy: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(User().Email),
                    DisplayName: User().FullName,
                    Email: User().Email,
                    Department: "",
                    JobTitle: "",
                    Picture: ""
                },
                LastUpdated: Now()
            }
        )
    );

    // 3. A setup that came along would otherwise still point at the old room.
    ForAll(
        // Each queued asset carries a table of setups, so they are
        // flattened into one list of titles before being deduplicated.
        Distinct(
            Ungroup(
                ForAll(colMoveBuffer As a, { setups: a.Setups }),
                setups),
            Value
        ) As s,
        If(
            !IsBlank(LookUp(Equipment_Setups, Titel = s.Value).'Id (ID)'),
            Patch(
                Equipment_Setups,
                LookUp(Equipment_Setups, Titel = s.Value),
                {
                    CurrentLocation: { Value: varMvRoom },
                    CurrentCampus: {
                        Value: Coalesce(
                            varMvCampus,
                            LookUp(Equipment_Setups, Titel = s.Value).CurrentCampus.Value
                        )
                    }
                }
            )
        )
    );

    // 4. Say what happened, either way.
    Set(
        varMvOk,
        IsEmpty(Errors(Equipment_Assets))
            && IsEmpty(Errors(Equipment_MovementLog))
            && IsEmpty(Errors(Equipment_Setups))
    );
    If(
        varMvOk,
        Clear(colMoveBuffer);
        Reset(drpTargetLocation);
        Notify("Move saved.", NotificationType.Success),
        Notify(
            "Save failed: " & Trim(
                Concat(Errors(Equipment_Assets), Message, " | ") & " " &
                Concat(Errors(Equipment_MovementLog), Message, " | ") & " " &
                Concat(Errors(Equipment_Setups), Message, " | ")
            ),
            NotificationType.Error
        )
    )
)

Set(varAddSid, ThisItem.Titel);
Set(
    varAddNew,
    Filter(
        Filter(Equipment_Assets, varAddSid in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
If(
    CountRows(varAddNew) = 0,
    Notify(
        "All assets from setup " & varAddSid & " are already in the list.",
        NotificationType.Warning
    ),
    Collect(colMoveBuffer, varAddNew);
    Notify(
        CountRows(varAddNew) & " asset(s) from setup " & varAddSid & " added.",
        NotificationType.Success
    )
);
Reset(txtMoveSearch)

Set(varAddSid, ThisItem.Titel);
Set(
    varAddNew,
    Filter(
        Filter(Equipment_Assets, varAddSid in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
If(
    CountRows(varAddNew) = 0,
    Notify(
        "All assets from setup " & varAddSid & " are already in the list.",
        NotificationType.Warning
    ),
    Collect(colMoveBuffer, varAddNew);
    Notify(
        CountRows(varAddNew) & " asset(s) from setup " & varAddSid & " added.",
        NotificationType.Success
    )
);
Reset(txtMoveSearch)

Set(varAddSid, ThisItem.Titel);
Set(
    varAddNew,
    Filter(
        Filter(Equipment_Assets, varAddSid in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
If(
    CountRows(varAddNew) = 0,
    Notify(
        "All assets from setup " & varAddSid & " are already in the list.",
        NotificationType.Warning
    ),
    Collect(colMoveBuffer, varAddNew);
    Notify(
        CountRows(varAddNew) & " asset(s) from setup " & varAddSid & " added.",
        NotificationType.Success
    )
);
Reset(txtMoveSearch)

Set(varAddSid, ThisItem.Titel);
Set(
    varAddNew,
    Filter(
        Filter(Equipment_Assets, varAddSid in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
If(
    CountRows(varAddNew) = 0,
    Notify(
        "All assets from setup " & varAddSid & " are already in the list.",
        NotificationType.Warning
    ),
    Collect(colMoveBuffer, varAddNew);
    Notify(
        CountRows(varAddNew) & " asset(s) from setup " & varAddSid & " added.",
        NotificationType.Success
    )
);
Reset(txtMoveSearch)

If(
    ThisItem.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify("This asset is already in the move list.", NotificationType.Warning),
    Collect(colMoveBuffer, ThisItem);
    Notify(ThisItem.Titel & " added.", NotificationType.Success);
    Reset(txtMoveSearch)
)

If(
    ThisItem.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify("This asset is already in the move list.", NotificationType.Warning),
    Collect(colMoveBuffer, ThisItem);
    Notify(ThisItem.Titel & " added.", NotificationType.Success);
    Reset(txtMoveSearch)
)

If(
    ThisItem.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify("This asset is already in the move list.", NotificationType.Warning),
    Collect(colMoveBuffer, ThisItem);
    Notify(ThisItem.Titel & " added.", NotificationType.Success);
    Reset(txtMoveSearch)
)

If(
    ThisItem.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify("This asset is already in the move list.", NotificationType.Warning),
    Collect(colMoveBuffer, ThisItem);
    Notify(ThisItem.Titel & " added.", NotificationType.Success);
    Reset(txtMoveSearch)
)
